"""Decode of the fictitious STERA F10 model (untrained, generated by systems/f10/generate_f10.py from the
final checkpoint H122000) for varying context lengths.

Mechanical test: the KV cache is filled with random values (global layers up to L positions, local layers
up to 256), then the decode steps t = L, ..., L+23 are timed. The attention really reads every occupied
position. Positions beyond 2047 reuse the last row of the position table: the test measures execution cost,
not long-context quality.
Usage: STERA_WEIGHTS=H122000 python f10_context.py --context 8192 --out file.json
Output keys are kept as in the archived results (contesto, capacita_cache, ...).
"""
import argparse, json, statistics, sys, time
from pathlib import Path
import mlx.core as mx
R = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(R / "engines"))
import stera_independent_fp32_longctx_v47 as LC
import stera4b_stream_mlx as S
sys.path.insert(0, str(R / "f10"))
import load_f10
LC.M.DirectIndependentModel = load_f10.F10FromFile   # the model is read from the generated file

ap = argparse.ArgumentParser(); ap.add_argument("--context", "--contesto", dest="context", type=int, required=True)
ap.add_argument("--steps", "--passi", dest="steps", type=int, default=24); ap.add_argument("--kv", default="fp32"); ap.add_argument("--out", required=True)
a = ap.parse_args()
L = a.context
cap = next(c for c in (512, 2048, 4096, 8192, 16384, 32768, 65536) if c >= L + a.steps)
m = LC.LongCompiled(cap, kv_precision=a.kv)
mx.random.seed(0)
# cache filled with random values; the references to the cache are released before every step, so that MLX
# updates the cache in place instead of copying it (as an engine in real use would)
kk = tuple(mx.random.normal(x.shape, dtype=x.dtype) * 0.5 for x in m.k)
vv = tuple(mx.random.normal(x.shape, dtype=x.dtype) * 0.5 for x in m.v)
m.k = m.v = None; mx.eval(kk, vv)
if hasattr(mx, "reset_peak_memory"): mx.reset_peak_memory()
tok = mx.array(50256, mx.int32); times = []
for i in range(a.steps + 3):
    t = L + i
    st = time.perf_counter()
    logits, nk, nv = m.fn(tok, mx.array(t, mx.int32), kk, vv)
    del kk, vv
    tok = mx.argmax(logits).astype(mx.int32); mx.eval(tok, nk, nv)
    kk, vv = nk, nv; del nk, nv
    times.append(time.perf_counter() - st)
dec = times[3:]
res = dict(contesto=L, capacita_cache=cap, kv=a.kv, passi=a.steps, modello=load_f10.FILE.name, sha256_modello=m.m.sourcehash, kv_byte=sum(x.nbytes for x in kk + vv),
           decode_tok_s=len(dec) / sum(dec), ms_mediana=1000 * statistics.median(dec),
           ms_p90=1000 * sorted(dec)[int(.9 * len(dec)) - 1], primo_passo_s=times[0],
           memoria=S.get_mem(), mlx_picco_mib=round(mx.get_peak_memory() / 2**20, 1) if hasattr(mx, "get_peak_memory") else None)
Path(a.out).write_text(json.dumps(res, indent=1)); print(json.dumps(res))
